const KEY = "winclaw.control.settings.v1";

import type { ThemeMode } from "./theme.ts";

export type UiSettings = {
  gatewayUrl: string;
  token: string;
  sessionKey: string;
  lastActiveSessionKey: string;
  theme: ThemeMode;
  chatFocusMode: boolean;
  chatShowThinking: boolean;
  splitRatio: number; // Sidebar split ratio (0.4 to 0.7, default 0.6)
  navCollapsed: boolean; // Legacy – kept for compat, unused in Notion-style layout
  navGroupsCollapsed: Record<string, boolean>; // Legacy – kept for compat
  openTabs: string[]; // Session tabs (Notion-style layout)
  recentCommands: string[]; // Command palette recent commands
  openChatSessions: string[]; // Open chat session keys (multi-session tabs)
  // 数字人秘书 A案 身份桥(docs/10 §14.5): DH URL の ?aimeta=&api= から取得。節点 UI が
  // ai-meta の /files /tasks を叩く scoped token + API base。空=秘书機能無効。
  aimetaToken: string;
  aimetaApi: string;
};

export function loadSettings(): UiSettings {
  const defaultUrl = (() => {
    const proto = location.protocol === "https:" ? "wss" : "ws";
    return `${proto}://${location.host}`;
  })();

  const defaults: UiSettings = {
    gatewayUrl: defaultUrl,
    token: "",
    sessionKey: "main",
    lastActiveSessionKey: "main",
    theme: "system",
    chatFocusMode: false,
    chatShowThinking: true,
    splitRatio: 0.6,
    navCollapsed: false,
    navGroupsCollapsed: {},
    openTabs: ["chat"],
    recentCommands: [],
    openChatSessions: [],
    aimetaToken: "",
    aimetaApi: "",
  };

  try {
    const raw = localStorage.getItem(KEY);
    if (!raw) {
      return defaults;
    }
    const parsed = JSON.parse(raw) as Partial<UiSettings>;
    return {
      gatewayUrl:
        typeof parsed.gatewayUrl === "string" && parsed.gatewayUrl.trim()
          ? parsed.gatewayUrl.trim()
          : defaults.gatewayUrl,
      token: typeof parsed.token === "string" ? parsed.token : defaults.token,
      sessionKey:
        typeof parsed.sessionKey === "string" && parsed.sessionKey.trim()
          ? parsed.sessionKey.trim()
          : defaults.sessionKey,
      lastActiveSessionKey:
        typeof parsed.lastActiveSessionKey === "string" && parsed.lastActiveSessionKey.trim()
          ? parsed.lastActiveSessionKey.trim()
          : (typeof parsed.sessionKey === "string" && parsed.sessionKey.trim()) ||
            defaults.lastActiveSessionKey,
      theme:
        parsed.theme === "light" || parsed.theme === "dark" || parsed.theme === "system"
          ? parsed.theme
          : defaults.theme,
      chatFocusMode:
        typeof parsed.chatFocusMode === "boolean" ? parsed.chatFocusMode : defaults.chatFocusMode,
      chatShowThinking:
        typeof parsed.chatShowThinking === "boolean"
          ? parsed.chatShowThinking
          : defaults.chatShowThinking,
      splitRatio:
        typeof parsed.splitRatio === "number" &&
        parsed.splitRatio >= 0.4 &&
        parsed.splitRatio <= 0.7
          ? parsed.splitRatio
          : defaults.splitRatio,
      navCollapsed:
        typeof parsed.navCollapsed === "boolean" ? parsed.navCollapsed : defaults.navCollapsed,
      navGroupsCollapsed:
        typeof parsed.navGroupsCollapsed === "object" && parsed.navGroupsCollapsed !== null
          ? parsed.navGroupsCollapsed
          : defaults.navGroupsCollapsed,
      openTabs:
        Array.isArray(parsed.openTabs) && parsed.openTabs.every((t) => typeof t === "string")
          ? parsed.openTabs
          : defaults.openTabs,
      recentCommands:
        Array.isArray(parsed.recentCommands) &&
        parsed.recentCommands.every((c) => typeof c === "string")
          ? parsed.recentCommands
          : defaults.recentCommands,
      openChatSessions:
        Array.isArray(parsed.openChatSessions) &&
        parsed.openChatSessions.every((s) => typeof s === "string")
          ? parsed.openChatSessions
          : defaults.openChatSessions,
      aimetaToken:
        typeof parsed.aimetaToken === "string" ? parsed.aimetaToken : defaults.aimetaToken,
      aimetaApi:
        typeof parsed.aimetaApi === "string" ? parsed.aimetaApi : defaults.aimetaApi,
    };
  } catch {
    return defaults;
  }
}

export function saveSettings(next: UiSettings) {
  localStorage.setItem(KEY, JSON.stringify(next));
}
